import{_ as t,o,c as r,ae as i}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"🚀 Deployment Guide: Render + Turso + Gemini","description":"","frontmatter":{},"headers":[],"relativePath":"deployment_guide.md","filePath":"deployment_guide.md"}'),n={name:"deployment_guide.md"};function a(l,e,s,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="🚀-deployment-guide-render-turso-gemini" tabindex="-1">🚀 Deployment Guide: Render + Turso + Gemini <a class="header-anchor" href="#🚀-deployment-guide-render-turso-gemini" aria-label="Permalink to &quot;🚀 Deployment Guide: Render + Turso + Gemini&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>This project uses a <strong>Cloud-Native Architecture</strong>:</p><ul><li><strong>Frontend</strong>: React (Vite) -&gt; Deployed as <strong>Static Site</strong> on Render.</li><li><strong>Backend</strong>: Node.js (Express) -&gt; Deployed as <strong>Web Service</strong> on Render.</li><li><strong>Database</strong>: <strong>Turso</strong> (LibSQL) -&gt; Serverless SQLite.</li><li><strong>AI</strong>: <strong>Google Genkit</strong> -&gt; Gemini 2.5 Flash.</li></ul><h2 id="_2-prerequisites" tabindex="-1">2. Prerequisites <a class="header-anchor" href="#_2-prerequisites" aria-label="Permalink to &quot;2. Prerequisites&quot;">​</a></h2><ul><li><a href="https://render.com" target="_blank" rel="noreferrer">Render Account</a> (Free Tier is sufficient).</li><li><a href="https://turso.tech" target="_blank" rel="noreferrer">Turso Account</a> (CLI installed).</li><li><a href="https://aistudio.google.com" target="_blank" rel="noreferrer">Google AI Studio Key</a>.</li></ul><h2 id="_3-deployment-steps-the-blueprint-way" tabindex="-1">3. Deployment Steps (The &quot;Blueprint&quot; Way) <a class="header-anchor" href="#_3-deployment-steps-the-blueprint-way" aria-label="Permalink to &quot;3. Deployment Steps (The &quot;Blueprint&quot; Way)&quot;">​</a></h2><p>The easiest way to deploy is using the <code>render.yaml</code> Blueprint.</p><ol><li><strong>Push your code</strong> to GitHub.</li><li><strong>Go to Render Dashboard</strong> -&gt; Blueprints -&gt; New Blueprint Instance.</li><li><strong>Connect your Repo</strong>.</li><li><strong>env details</strong>: Render will ask for these variables.</li></ol><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><code>TURSO_DB_URL</code></td><td style="text-align:left;">Turso Database Connection URL</td><td style="text-align:left;"><code>libsql://tendercheck-ai-ely.turso.io</code></td></tr><tr><td style="text-align:left;"><code>TURSO_AUTH_TOKEN</code></td><td style="text-align:left;">Turso Auth Token</td><td style="text-align:left;"><code>ey...</code></td></tr><tr><td style="text-align:left;"><code>GOOGLE_GENAI_API_KEY</code></td><td style="text-align:left;">Gemini API Key</td><td style="text-align:left;"><code>AIza...</code></td></tr><tr><td style="text-align:left;"><code>GOOGLE_API_KEY</code></td><td style="text-align:left;">Standard Google AI Key</td><td style="text-align:left;"><code>AIza...</code></td></tr><tr><td style="text-align:left;"><code>VITE_GOOGLE_CLIENT_ID</code></td><td style="text-align:left;">Google OAuth Client ID</td><td style="text-align:left;"><code>123...apps.googleusercontent.com</code></td></tr><tr><td style="text-align:left;"><code>VITE_API_BASE_URL</code></td><td style="text-align:left;">Backend URL (Important for Auth)</td><td style="text-align:left;"><code>https://tendercheck-backend.onrender.com</code></td></tr><tr><td style="text-align:left;"><code>JWT_SECRET</code></td><td style="text-align:left;">Secret for verifying tokens</td><td style="text-align:left;"><code>any_long_random_string</code></td></tr><tr><td style="text-align:left;"><code>SENTRY_DSN</code></td><td style="text-align:left;">(Optional) Sentry DSN</td><td style="text-align:left;"><code>https://...@sentry.io/...</code></td></tr></tbody></table><h2 id="_4-manual-deployment-alternative" tabindex="-1">4. Manual Deployment (Alternative) <a class="header-anchor" href="#_4-manual-deployment-alternative" aria-label="Permalink to &quot;4. Manual Deployment (Alternative)&quot;">​</a></h2><p>If you prefer manual setup:</p><h3 id="backend-web-service" tabindex="-1">Backend (Web Service) <a class="header-anchor" href="#backend-web-service" aria-label="Permalink to &quot;Backend (Web Service)&quot;">​</a></h3><ul><li><strong>Build Command</strong>: <code>cd backend &amp;&amp; npm install &amp;&amp; npm run build</code></li><li><strong>Start Command</strong>: <code>cd backend &amp;&amp; npm start</code></li><li><strong>Env Vars</strong>: Add the variables above.</li></ul><h3 id="frontend-static-site" tabindex="-1">Frontend (Static Site) <a class="header-anchor" href="#frontend-static-site" aria-label="Permalink to &quot;Frontend (Static Site)&quot;">​</a></h3><ul><li><strong>Build Command</strong>: <code>cd frontend &amp;&amp; npm install &amp;&amp; npm run build</code></li><li><strong>Publish Directory</strong>: <code>frontend/dist</code></li><li><strong>Env Vars</strong>: <code>VITE_GOOGLE_CLIENT_ID</code> needs to be set <em>during build</em>.</li></ul><h2 id="_5-render-free-tier-lifecycle-⏳" tabindex="-1">5. Render Free Tier &amp; Lifecycle ⏳ <a class="header-anchor" href="#_5-render-free-tier-lifecycle-⏳" aria-label="Permalink to &quot;5. Render Free Tier &amp; Lifecycle ⏳&quot;">​</a></h2><p><strong>How it works:</strong></p><ul><li><strong>Spin Down</strong>: Your Backend (Web Service) will <strong>&quot;go to sleep&quot;</strong> after 15 minutes of inactivity to save resources.</li><li><strong>Spin Up</strong>: The next time you (or a user) opens the URL, it will take <strong>~50 seconds</strong> to wake up. This is normal.</li><li><strong>750 Hours</strong>: The Free Tier gives you 750 hours/month (enough for 24/7 if you only have one service, or plenty for testing).</li><li><strong>Database</strong>: Turso is serverless and does <em>not</em> sleep (always fast).</li></ul><h2 id="_6-gemini-api-pricing-tiers-🤖💰" tabindex="-1">6. Gemini API Pricing &amp; Tiers 🤖💰 <a class="header-anchor" href="#_6-gemini-api-pricing-tiers-🤖💰" aria-label="Permalink to &quot;6. Gemini API Pricing &amp; Tiers 🤖💰&quot;">​</a></h2><p>This project is compatible with the <strong>Google AI Studio Free Tier</strong>. However, your specific cost will depend on your project&#39;s configuration:</p><h3 id="_1-free-tier-zero-cost" tabindex="-1">1. Free Tier (Zero Cost) <a class="header-anchor" href="#_1-free-tier-zero-cost" aria-label="Permalink to &quot;1. Free Tier (Zero Cost)&quot;">​</a></h3><ul><li><strong>Conditions</strong>: Your Google Cloud project <strong>must not</strong> have a billing account attached.</li><li><strong>Limits</strong>: Lower rate limits (e.g., 15 requests per minute).</li><li><strong>Data Policy</strong>: Google may use your data to improve their models.</li></ul><h3 id="_2-pay-as-you-go-tier-paid" tabindex="-1">2. Pay-as-you-go Tier (Paid) <a class="header-anchor" href="#_2-pay-as-you-go-tier-paid" aria-label="Permalink to &quot;2. Pay-as-you-go Tier (Paid)&quot;">​</a></h3><ul><li><strong>Condition</strong>: If you link a <strong>Credit Card / Billing Account</strong> to your Google Cloud Project, it automatically switches to the paid tier.</li><li><strong>Costs</strong>: You are charged per 1M characters (input/output). This is what causes the €0.35 charges seen in reports.</li><li><strong>Data Policy</strong>: Your data is <strong>private</strong> and not used for model training.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If you see charges in your Google Cloud report (like &quot;Gemini API Output Tokens&quot;), it means your project is in the <strong>Pay-as-you-go</strong> tier. To avoid this, ensure no billing account is linked to your <code>gen-lang-client-...</code> project in the <a href="https://console.cloud.google.com/billing" target="_blank" rel="noreferrer">GCP Billing Console</a>.</p></div><hr><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><p>If the backend fails to start, check the &quot;Logs&quot; tab in Render.</p><ul><li><strong>&quot;Table not found&quot;</strong>: Ensure <code>SqliteDatabase.initializeSchema()</code> ran correctly (it should run automatically on startup).</li><li><strong>CORS Errors</strong>: <ul><li>Verify <code>ALLOWED_ORIGINS</code> in Render environment matches your frontend URL (<code>https://your-app.onrender.com</code>).</li><li><strong>Allowed Headers</strong>: If seeing CORS errors on &quot;Hard Reload&quot;, ensure backend allows <code>Cache-Control</code>, <code>Pragma</code>, and <code>Expires</code>.</li></ul></li><li><strong>&quot;Google Auth Error: redirect_uri_mismatch&quot;</strong>: <ol><li>Go to <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noreferrer">Google Cloud Console &gt; Credentials</a>.</li><li>Edit your OAuth 2.0 Client ID.</li><li>Under <strong>Authorized JavaScript origins</strong>, ADD your Render URL (e.g., <code>https://tendercheck-frontend.onrender.com</code>).</li><li>Under <strong>Authorized redirect URIs</strong>, ADD the same URL (just in case).</li><li><strong>Wait 5 minutes</strong> (Google takes time to propagate changes).</li></ol></li></ul><p><strong>Enjoy your scalable, cloud-native AI app!</strong> 🚀</p>',32)])])}const p=t(n,[["render",a]]);export{h as __pageData,p as default};
